A handler that catches a value error replaces it with a type error and names the original as the cause, then the replacement is caught at the top and three of its recorded links are read. The program below is run under CPython 3.14.3. What does it print?

def inner():
    raise ValueError("inner failed")


def outer():
    try:
        inner()
    except ValueError as exc:
        raise TypeError("outer failed") from exc


try:
    outer()
except TypeError as exc:
    print(type(exc).__name__, exc)
    print(type(exc.__cause__).__name__, exc.__cause__)
    print(exc.__cause__ is exc.__context__)
    print(exc.__suppress_context__)
    print(getattr(exc.__cause__, "__traceback__", None) is not None)

A helper divides a hundred by each value in turn and records a marker whenever the divisor is zero, and the same walk is then written out by hand for comparison. The program below is run under CPython 3.14.3. What does it print?

def step(n):
    return 100 // n


def run(values):
    seen = []
    for v in values:
        try:
            seen.append(step(v))
        except ZeroDivisionError:
            seen.append("skip")
    return seen


print(run([4, 0, 5, 0]))
seen = []
for v in [4, 0, 5, 0]:
    try:
        seen.append(step(v))
    except ZeroDivisionError:
        seen.append("skip")
print(seen)
print(seen == run([4, 0, 5, 0]))
print(len(seen))

A function that raises a runtime error is wrapped by a caller that catches it and raises a lookup error of its own, and the top level then reports what the replacement recorded. The program below is run under CPython 3.14.3. What does it print?

import sys


def spin():
    raise RuntimeError("inner")


def outer():
    try:
        spin()
    except RuntimeError:
        raise LookupError("outer")


try:
    outer()
except LookupError as exc:
    print(type(exc).__name__, exc)
    print(type(exc.__context__).__name__, exc.__context__)
    print(exc.__cause__)
    print(exc.__suppress_context__)
    print(sys.exc_info()[0] is LookupError)

A validating helper attaches two pieces of extra context to the error it is about to let go of, and a separate plain error is then inspected before and after a note is added to it. The program below is run under CPython 3.14.3. What does it print?

def check(value):
    try:
        if value < 0:
            raise ValueError("negative input")
        return value * 2
    except ValueError as exc:
        exc.add_note(f"while handling value {value}")
        exc.add_note("second note")
        raise


for v in (3, -1):
    try:
        print(check(v))
    except ValueError as exc:
        print(exc)
        for note in getattr(exc, "__notes__", []):
            print("note:", note)

bare = ValueError("bare")
print(hasattr(bare, "__notes__"))
bare.add_note("now it exists")
print(bare.__notes__)
print(bare)

Four calls are made, two of which raise a group holding one error of each of two different types, and each call is run past three separate star handlers before the class hierarchy is reported. The program below is run under CPython 3.14.3. What does it print?

def go(mode):
    if mode == "a":
        raise KeyError("missing key")
    if mode == "b":
        raise ValueError("bad value")
    if mode == "c":
        raise ExceptionGroup("pair", [KeyError("k1"), ValueError("v1")])
    raise ExceptionGroup("pair", [ValueError("v2"), TypeError("t2")])


for mode in ("a", "b", "c", "d"):
    try:
        go(mode)
    except* KeyError as eg:
        print("keys", type(eg).__name__, len(eg.exceptions))
    except* ValueError as eg:
        print("values", type(eg).__name__, len(eg.exceptions))
    except* TypeError as eg:
        print("types", type(eg).__name__, len(eg.exceptions))

print(ExceptionGroup.__bases__[0].__name__)
print(issubclass(ExceptionGroup, Exception))

Three named steps are run and every failure is collected, the collected errors are packed into a group, and one type is then taken out of that group with the original printed again afterwards. The program below is run under CPython 3.14.3. What does it print?

def check_all(items):
    problems = []
    for name, fn in items:
        try:
            fn()
        except (ValueError, TypeError) as exc:
            problems.append(exc)
    return problems


def a():
    raise ValueError("a")


def b():
    raise ValueError("b")


def c():
    raise TypeError("c")


errs = check_all([("a", a), ("b", b), ("c", c)])
print(len(errs))
eg = ExceptionGroup("all failures", errs)
print(eg)
sub = eg.subgroup(ValueError)
print(type(sub).__name__, len(sub.exceptions))
print([str(e) for e in sub.exceptions])
print([str(e) for e in eg.exceptions])

The current handler information is inspected at three points: outside any handler, inside a handler, and after a nested handler has finished. The program below is run under CPython 3.14.3. What does it print?

import sys

print(sys.exc_info() == (None, None, None))


def probe():
    return [type(x).__name__ for x in sys.exc_info()]


print(probe())


def guarded():
    try:
        1 / 0
    except ZeroDivisionError as exc:
        return sys.exc_info()[1] is exc, exc.__traceback__ is not None


print(guarded())
try:
    try:
        1 / 0
    except ZeroDivisionError:
        held = sys.exc_info()[1]
finally:
    pass
print(type(held).__name__)
print(sys.exc_info() == (None, None, None))

One caller wraps another that can raise one of two different errors, and the call is made three times, once per failure and once with no failure at all. The program below is run under CPython 3.14.3. What does it print?

def risky(n):
    if n == 0:
        raise ValueError("no")
    if n == 1:
        raise TypeError("bad type")
    return n


def caller(n):
    try:
        return risky(n)
    except ValueError as exc:
        print("value handler", exc)
        return "recovered"
    except TypeError as exc:
        print("type handler", exc)
        return "also recovered"
    else:
        print("else branch")
        return "clean"
    finally:
        print("finally", n)


print(caller(0))
print(caller(1))
print(caller(3))

A decorated generator reports when it starts, hands a value to the body, and distinguishes the clean path from the failing one before cleaning up, and the with block around it is then used once cleanly and once with an error raised inside. The program below is run under CPython 3.14.3. What does it print?

import contextlib


@contextlib.contextmanager
def noisy():
    print("enter")
    try:
        yield "value"
    except ValueError as exc:
        print("saw", type(exc).__name__)
        raise
    else:
        print("no error")
    finally:
        print("cleanup")


with noisy() as got:
    print("body", got)

print("---")

try:
    with noisy() as got:
        print("body", got)
        raise ValueError("boom")
except ValueError as exc:
    print("outside", exc)

A custom error takes the stage it failed at and the error behind it, builds its own message, and is raised from that error; the helper is then called once without a failure and once with one. The program below is run under CPython 3.14.3. What does it print?

class PipelineError(Exception):
    def __init__(self, stage, cause):
        super().__init__(f"stage {stage} failed")
        self.stage = stage
        self.cause = cause


def run(stage, fail):
    try:
        if fail:
            raise KeyError(f"missing in {stage}")
        return "ok"
    except KeyError as exc:
        raise PipelineError(stage, exc) from exc


print(run("load", False))
try:
    run("load", True)
except PipelineError as exc:
    print(exc)
    print(exc.stage)
    print(type(exc.cause).__name__, exc.cause)
    print(exc.args)
    print(exc.__cause__ is exc.cause)
